  "pages": [
    {
      "id": "about",
      "slug": "about",
      "title": {
        "ar": "من نحن",
        "en": "About us"
      },
      "body": {
        "ar": "سيارتك سوق للسيارات وخدماتها في السودان. نجمع البائعين والمشترين والورش والميكانيكيين في مكان واحد.",
        "en": "Sayaratak is a marketplace for vehicles and auto services in Sudan. It brings sellers, buyers, workshops and mechanics together."
      }
    },
    {
      "id": "contact",
      "slug": "contact",
      "title": {
        "ar": "اتصل بنا",
        "en": "Contact us"
      },
      "body": {
        "ar": "يسعدنا سماع رأيك. راسلنا في أي وقت.",
        "en": "We would like to hear from you. Write to us any time."
      }
    },
    {
      "id": "privacy",
      "slug": "privacy",
      "title": {
        "ar": "سياسة الخصوصية",
        "en": "Privacy policy"
      },
      "body": {
        "ar": "نحتفظ ببياناتك لتشغيل الخدمة فقط ولا نبيعها لأي جهة.\n\n# ما الذي نجمعه\n- الاسم ورقم الهاتف أو البريد الإلكتروني\n- الإعلانات والرسائل التي ترسلها عبر الموقع\n\n# حقوقك\nيمكنك طلب حذف حسابك وبياناتك في أي وقت عبر صفحة اتصل بنا.",
        "en": "We keep your data only to run the service and never sell it.\n\n# What we collect\n- Your name and your phone number or email\n- The listings and messages you send through the site\n\n# Your rights\nYou can ask us to delete your account and data at any time from the contact page."
      }
    },
    {
      "id": "terms",
      "slug": "terms",
      "title": {
        "ar": "الشروط والأحكام",
        "en": "Terms"
      },
      "body": {
        "ar": "باستخدامك الموقع فأنت توافق على نشر معلومات صحيحة والالتزام بقواعد المجتمع.\n\n# قواعد النشر\n- انشر مركبات وخدمات حقيقية فقط\n- اذكر السعر الصحيح بالجنيه السوداني\n- لا تنشر إعلانا مكررا\n\n# الإيقاف\nقد نوقف الإعلانات أو الحسابات المخالفة.",
        "en": "By using the site you agree to post accurate information and follow the community rules.\n\n# Posting rules\n- Post real vehicles and services only\n- State the correct price in Sudanese pounds\n- Do not post the same listing twice\n\n# Suspension\nWe may suspend listings or accounts that break these rules."
      }
    }
  ]
